effect.shader:
float hash1(float x) {
    return fract(sin(x * 127.1 + float(seed) * 13.7) * 43758.5453);
}

/** Ruído suave 1D (interpolação smoothstep entre hashes). */
float ruido1(float x) {
    float i = floor(x);
    float f = fract(x);
    float s = f * f * (3.0 - 2.0 * f);
    return mix(hash1(i), hash1(i + 1.0), s);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    // A fonte "respira" andando devagar num círculo pequeno.
    float t = acTime * speed;
    vec2 andanca = vec2(ruido1(t * 0.37 + 1.3) - 0.5, ruido1(t * 0.41 + 7.7) - 0.5);
    vec2 fonte = sourceAt + andanca * 0.08;
    fonte = vec2(fonte.x * acAspect, fonte.y);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y);
    float d = length(p - fonte);

    // Gradiente radial exponencial: luz forte perto, desvanece longe.
    float gradiente = exp(-d / max(spread, 1e-4));

    // Respirar: a intensidade oscila devagar.
    float pulsacao = mix(1.0, 0.5 + 0.5 * ruido1(t * 0.9 + 2.7), breathe);

    float forca = gradiente * intensity * pulsacao * leakColor.a;

    vec3 luz = leakColor.rgb * forca;

    // Mistura por SCREEN: 1 − (1−orig)(1−luz). Luz nunca escurece pixel claro.
    vec3 cor = 1.0 - (1.0 - original.rgb) * (1.0 - luz);
    cor = mix(original.rgb, cor, clamp(forca, 0.0, 1.0));

    fragColor = vec4(cor, original.a);
}
